<?php
require_once __DIR__.'/includes/auth.php';
$token=(string)($_GET['token']??'');if(!preg_match('/^[a-f0-9]{64}$/',$token)||setting('public_sharing_enabled','1')!=='1'){http_response_code(404);exit('Share link not found.');}
$stmt=db()->prepare('SELECT s.*,a.*,u.name uploader_name,c.name category_name FROM share_links s JOIN assets a ON a.id=s.asset_id JOIN users u ON u.id=a.uploaded_by LEFT JOIN categories c ON c.id=a.category_id WHERE s.token=? AND s.is_active=1 AND a.deleted_at IS NULL AND (s.expires_at IS NULL OR s.expires_at>NOW())');$stmt->execute([$token]);$share=$stmt->fetch();if(!$share){http_response_code(404);exit('This share link is invalid, disabled, or expired.');}
$error='';if($share['password_hash']&&!empty($_POST['password'])){verify_csrf();if(password_verify((string)$_POST['password'],$share['password_hash'])){$_SESSION['share_access'][$token]=true;session_regenerate_id(true);header('Location: '.url('share.php?token='.$token));exit;}else $error='Incorrect password.';}
$unlocked=!$share['password_hash']||!empty($_SESSION['share_access'][$token]);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($share['title'])?> · Shared asset</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="<?=e(url('assets/css/app.css'))?>" rel="stylesheet"></head><body><nav class="navbar bg-white border-bottom"><div class="container"><span class="navbar-brand d-flex align-items-center gap-2"><span class="brand-mark text-white"><i class="bi bi-layers-fill"></i></span><?=e(setting('system_name',APP_NAME))?></span><span class="badge text-bg-light"><i class="bi bi-shield-check me-1"></i>Secure share</span></div></nav><main class="container py-5"><?php if(!$unlocked):?><div class="card mx-auto" style="max-width:430px"><div class="card-body p-5 text-center"><i class="bi bi-lock display-4 text-primary"></i><h1 class="h4 mt-3">Password protected</h1><p class="text-muted">Enter the password provided by the person who shared this asset.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><input class="form-control mb-3" type="password" name="password" required autofocus><button class="btn btn-primary w-100">Unlock asset</button></form></div></div><?php else:?><div class="row g-4"><div class="col-lg-8"><div class="card"><div class="card-body p-3"><div class="preview-stage"><?php if(in_array($share['file_extension'],['jpg','jpeg','png','gif','webp','svg'],true)):?><img src="<?=e(url('preview.php?id='.$share['asset_id'].'&token='.$token))?>" alt="<?=e($share['title'])?>"><?php elseif($share['file_extension']==='pdf'):?><iframe src="<?=e(url('preview.php?id='.$share['asset_id'].'&token='.$token))?>" width="100%" height="600"></iframe><?php elseif(in_array($share['file_extension'],['mp4','webm'],true)):?><video controls src="<?=e(url('preview.php?id='.$share['asset_id'].'&token='.$token))?>"></video><?php elseif(in_array($share['file_extension'],['mp3','wav'],true)):?><audio class="w-75" controls src="<?=e(url('preview.php?id='.$share['asset_id'].'&token='.$token))?>"></audio><?php else:?><div class="text-center"><i class="bi <?=e(asset_icon($share['file_extension']))?> display-1 text-primary"></i><p class="mt-3"><?=e($share['original_filename'])?></p></div><?php endif;?></div></div></div></div><div class="col-lg-4"><div class="card"><div class="card-body p-4"><span class="badge badge-soft text-uppercase mb-2"><?=e($share['file_extension'])?></span><h1 class="h4"><?=e($share['title'])?></h1><p class="text-muted"><?=nl2br(e($share['description']?:'No description provided.'))?></p><hr><dl class="row small"><dt class="col-5 text-muted fw-normal">Filename</dt><dd class="col-7 text-break"><?=e($share['original_filename'])?></dd><dt class="col-5 text-muted fw-normal">Size</dt><dd class="col-7"><?=e(human_file_size((int)$share['file_size']))?></dd><dt class="col-5 text-muted fw-normal">Category</dt><dd class="col-7"><?=e($share['category_name']??'—')?></dd><dt class="col-5 text-muted fw-normal">Shared by</dt><dd class="col-7"><?=e($share['uploader_name'])?></dd><dt class="col-5 text-muted fw-normal">Expires</dt><dd class="col-7"><?=e($share['expires_at']?date('M j, Y',strtotime($share['expires_at'])):'Never')?></dd></dl><?php if($share['download_allowed']):?><a class="btn btn-primary w-100" href="<?=e(url('download.php?id='.$share['asset_id'].'&token='.$token))?>"><i class="bi bi-download me-2"></i>Download asset</a><?php else:?><div class="alert alert-info mb-0 small"><i class="bi bi-eye me-1"></i>This link is view-only.</div><?php endif;?></div></div></div></div><?php endif;?></main></body></html>

